          "instruction": "Draw an upward-pointing triangle.\nUse triangle(x1, y1, x2, y2, x3, y3) with vertices at (200, 50), (100, 300), (300, 300).\n",
          "validation": [
            {
              "type": "functionCall",
              "name": "triangle",
              "exactArgs": 6
            },

