         card.style.position = 'absolute';
       }
     }
   }

   function next() {
     if (tutStep < 0) return;
     if (tutStep >= steps.length - 1) {
       ov.style.display = 'none';
       localStorage.setItem(TUT_KEY, '1');
       return;
